<template><div class="form-view"><div class="form-heading"><span class="form-kicker">WELCOME BACK</span><h2>登录 Creator SN</h2><p>继续你的创造之旅。</p></div><form @submit.prevent="submit"><label>账号<input v-model.trim="form.userid" autocomplete="username" placeholder="邮箱、字母或数字" /></label><label>密码<input v-model="form.pwd" type="password" autocomplete="current-password" placeholder="至少 6 位密码" /></label><p v-if="error" class="error">{{ error }}</p><button class="primary-button" :disabled="loading">{{ loading ? "登录中…" : "登录" }}</button></form><div class="form-foot"><span>还没有账号？</span><router-link to="/login/register">使用邀请码注册</router-link></div></div></template>
<script setup>
import { reactive, ref } from "vue";import { useRoute,useRouter } from "vue-router";import { UserApi } from "@/api";import { useUserStore } from "@/stores/useUser";
const router=useRouter(),route=useRoute(),user=useUserStore(),form=reactive({userid:"",pwd:""}),loading=ref(false),error=ref("");
async function submit(){if(!form.userid||!form.pwd){error.value="请输入账号和密码";return}loading.value=true;error.value="";try{const result=await UserApi.login(form);if(result.code!==200)throw new Error(result.message||"登录失败");user.setSession(result.data);await user.loadMe().catch(()=>{});router.push(route.query.return_url||"/")}catch(e){error.value=e.message||"登录失败"}finally{loading.value=false}}
</script>
<style scoped lang="scss">.form-view{display:grid;gap:24px}.form-heading h2{margin:8px 0;font-size:28px}.form-heading p{margin:0;color:#817b93}.form-kicker{font-size:11px;color:#b25fba;letter-spacing:.16em;font-weight:800}form{display:grid;gap:16px}label{display:grid;gap:7px;font-size:13px;color:#504867;font-weight:700}input{width:100%;padding:13px 14px;border:1px solid #e1d8ee;border-radius:12px;background:rgba(255,255,255,.8);font:inherit;outline:none}input:focus{border-color:#ca83d4;box-shadow:0 0 0 4px rgba(202,131,212,.12)}.primary-button{padding:14px;border:0;border-radius:12px;background:linear-gradient(120deg,#9c69d7,#e27bc7);color:#fff;font-weight:800;font-size:15px;cursor:pointer}.primary-button:disabled{opacity:.6}.error{margin:-5px 0;color:#ba4e70;font-size:13px}.form-foot{font-size:13px;color:#817b93}.form-foot a{margin-left:6px;color:#8759b6;font-weight:700;text-decoration:none}</style>
